"""Pinned Tessera recipe; all graph media names are generated by the service."""
VERSION='tessera-930c882-studio-3'
COMMIT='930c882a17fb9a494308ac0f19ed3a73fa9a4ce0'
PROMPT=('subject_definitions:\n<Video 1>: the complete source video. Preserve its subjects, framing, '
        'motion, timing, colors and lighting.\nretention_analysis:\n<Video 1>: fully_preserved. '
        'Enhance fine details naturally. Do not change identities, shapes, text or camera motion.')
PROFILES={
    'balanced':dict(label='Equilibrado',flat_skip=4.0,guide_release=.8),
    'high':dict(label='Alta calidad',flat_skip=2.0,guide_release=.8),
    'maximum':dict(label='Máxima calidad',flat_skip=0.0,guide_release=.8),
}
MODELS={
    'unet':'minimax_h3_ref2va_pruned_int8_convrot.safetensors',
    'clip':'qwen3vl_32b_minimax_h3_int8_convrot.safetensors',
    'vae':'minimax_h3_video_vae_int8_convrot.safetensors',
    'audio_vae':'minimax_h3_audio_vae_fp32.safetensors',
    'turbo':'minimax_h3_taomate_3step_lora_avg_rank_19_bf16.safetensors',
    'detail':'minimax_h3_lms_v1.0_r64.safetensors',
}

def ladder(frames): return max(22,frames+(5-frames)%17)

def graph(filename, job_id, width, height, frames, profile='balanced', advanced=None):
    a=advanced or {};p=PROFILES[profile]
    g={}
    def node(key,kind,**inputs):g[key]={'class_type':kind,'inputs':inputs};return [key,0]
    model=node('model','UNETLoader',unet_name=MODELS['unet'],weight_dtype='default')
    clip=node('clip','CLIPLoader',clip_name=MODELS['clip'],type='minimax',device='default')
    vae=node('vae','VAELoader',vae_name=MODELS['vae'])
    avae=node('audio_vae','VAELoader',vae_name=MODELS['audio_vae'])
    turbo=node('turbo','LoraLoaderModelOnly',model=model,lora_name=MODELS['turbo'],strength_model=1.)
    main=node('detail','LoraLoaderModelOnly',model=turbo,lora_name=MODELS['detail'],strength_model=.75)
    fine=node('fine','LoraLoaderModelOnly',model=model,lora_name=MODELS['detail'],strength_model=1.)
    video=node('load','LoadVideo',file=filename)
    images=node('components','GetVideoComponents',video=video)
    positive=node('reference','MiniMaxH3ReferenceToVideo',clip=clip,vae=vae,prompt=PROMPT,
        width=width,height=height,length=frames,ref_image_size='match',**{'ref_videos.ref_video_0':images})
    enc=node('encode','TesseraEncode',images=images,vae=vae,positive=positive,upscale_by=2.,
        upscale_method='lanczos',segment_frames=a.get('encode_window',39))
    empty=node('silence','EmptyAudio',duration=frames/24,sample_rate=44100,channels=2)
    al=node('audio','VAEEncodeAudio',audio=empty,vae=avae)
    latent=node('av','LTXVConcatAVLatent',video_latent=['encode',1],audio_latent=al)
    neg=node('negative','ConditioningZeroOut',conditioning=enc)
    sampler=node('sampler','KSamplerSelect',sampler_name='er_sde')
    tail=node('tail','KSamplerSelect',sampler_name='euler')
    sigmas=node('sigmas','ManualSigmas',sigmas='1, 0.7, 0.4, 0')
    args=node('options','TesseraArgs',video_ref_crop='per_tile',image_ref_crop='whole',guide_noise=0.,
        guide_noise_band='full',guide_noise_t='per_frame',guide_release=p['guide_release'],guide_inherit=True,
        hero_guide_noise=-1.,motion_adapt=True,motion_release_floor=0.,fine_below_sigma=.75,
        tile_select='',tile_limit=0,flat_skip=p['flat_skip'])
    node('refine','TesseraRefine',model=main,model_fine=fine,clip=clip,positive=enc,negative=neg,latent=latent,
        vae=vae,sampler=sampler,sampler_fine=tail,sigmas=sigmas,args=args,spatial_tile='custom',
        tile_width=a.get('tile_size',768),tile_height=a.get('tile_size',768),temporal_tile='custom',
        temporal_size=a.get('temporal_window',73),temporal_overlap=4,context_border=64,seam_overlap=32,
        hero_min=0,hero_fit='median',cfg=1.,seed=a.get('seed',786110),seed_mode='global',
        pixel_out=True,console_progress='overall',prompt=PROMPT)
    pixels=node('pixels','GenStudioTesseraOutput',images=['refine',2],latent=['refine',0],vae=vae,report=['refine',1])
    out=node('video','CreateVideo',images=pixels,fps=24.)
    node('save','SaveVideo',video=out,filename_prefix='gen_studio/'+job_id+'/tessera',format='mp4',codec='h264')
    return g
